\[\begin{aligned}
f(x, y, z) &amp; =x y z \\
\overline{\nabla f} &amp; =\hat{i} f_{x}+\hat{j} f_{y}+\hat{k} f_{z} \\
&amp; =\hat{i}(y z)+\hat{j}(x z)+\hat{k}(x y) \\
\overline{\nabla f}_{(0,2,1)} &amp; =\hat{i}(2)+0 \hat{j}+0 \hat{k}
\end{aligned}\]
<br/><br/>
Directional derivative,
<br/>
\[\begin{aligned}
D \cdot D &amp; =\overline{\nabla f} \cdot \frac{\bar{a}}{|\bar{a}|} \\
&amp; =(2 \hat{i}+0 \hat{j}+0 \hat{k}) \cdot \frac{(2 \hat{i}+\hat{j}+2 \hat{k})}{\sqrt{2^{2}+1^{2}+2^{2}}}=\frac{4}{\sqrt{9}}=\frac{4}{3}
\end{aligned}\]

